import java.util.Arrays;

public class Main {
    public static void main(String[] args) {
        String csv = "12,7,30,5";
        String[] parts = csv.split(",");
        int sum = 0;
        for (String part : parts) {
            sum += Integer.parseInt(part);
        }
        System.out.println(Arrays.toString(parts) + " sum " + sum);

        String version = "1.10.3";
        String[] nums = version.split("\\.");
        int minor = Integer.parseInt(nums[1]);
        System.out.println("Minor: " + minor + ", next: " + (minor + 1));
        System.out.println("Unescaped pieces: " + version.split(".").length);

        String sentence = "  learn   java   fast ";
        String[] words = sentence.strip().split("\\s+");
        System.out.println(words.length + " words: " + Arrays.toString(words));
        System.out.println(String.join("-", words));
        System.out.println(String.join(" | ", nums[0], nums[1], nums[2]));
    }
}

